<script id="aicore-pure">
// Pure helpers: no DOM globals, no network. Tested under node
// (test/test_aicore_page.lua). Every piece of text from the controller or
// the cloud is set with textContent; nothing is ever parsed as HTML.
var AIC = (function () {
  var A = {};
  A.PINLOCK_PORT = 47831;
  A.MAX_PIN = 8;
  A.parseQuery = function (search) {
    var out = {};
    String(search || '').replace(/^\?/, '').split('&').forEach(function (kv) {
      if (!kv) { return; }
      var i = kv.indexOf('=');
      var k = i < 0 ? kv : kv.slice(0, i);
      var v = i < 0 ? '' : kv.slice(i + 1);
      try { out[decodeURIComponent(k)] = decodeURIComponent(v); } catch (e) { /* ignored */ }
    });
    return out;
  };
  // The PIN may go to one place only: PIN Lock's /verify on THIS host.
  A.validVerifyUrl = function (url, pageHost) {
    var m = /^http:\/\/([A-Za-z0-9.\-]+):(\d+)\/verify$/.exec(String(url || ''));
    return !!m && m[1] === pageHost && Number(m[2]) === A.PINLOCK_PORT;
  };
  A.verifyBody = function (challengeId, pin) {
    return JSON.stringify({ challenge_id: String(challengeId), pin: String(pin) });
  };
  A.padAdd = function (cur, digit) {
    cur = String(cur || '');
    if (!/^[0-9]$/.test(String(digit)) || cur.length >= A.MAX_PIN) { return cur; }
    return cur + digit;
  };
  A.padBack = function (cur) { return String(cur || '').slice(0, -1); };
  A.dots = function (cur) { return new Array(String(cur || '').length + 1).join('•'); };
  A.lockText = function (seconds) {
    var s = Math.max(0, Math.floor(Number(seconds) || 0));
    return s <= 60 ? 'PIN entry is locked for ' + s + ' s' : 'PIN entry is locked for ' + Math.ceil(s / 60) + ' min';
  };
  A.leftText = function (seconds) {
    var s = Math.max(0, Math.floor(Number(seconds) || 0));
    return s >= 60 ? 'Locks again after ' + Math.ceil(s / 60) + ' min without use' : 'Locks again in ' + s + ' s';
  };
  A.riskText = function (risk) { return risk === 'medium' ? 'Risk: medium' : risk === 'low' ? 'Risk: low' : ''; };
  // Poll fast while something is pending, slowly when idle.
  A.pollDelay = function (st) {
    if (!st || !st.ok) { return 10000; }
    if (st.prompt || (st.review && st.review.loading)) { return 3000; }
    var conv = (st.chat && st.chat.conversation) || [];
    for (var i = 0; i < conv.length; i++) { if (conv[i].state === 'pending') { return 3000; } }
    return 30000;
  };
  A.el = function (doc, tag, cls, text) {
    var e = doc.createElement(tag);
    if (cls) { e.className = cls; }
    if (text !== undefined && text !== null) { e.textContent = String(text); }
    return e;
  };
  A.clear = function (root) { while (root.firstChild) { root.removeChild(root.firstChild); } };
  A.renderLines = function (doc, root, lines) {
    A.clear(root);
    (lines || []).forEach(function (t) { if (t) { root.appendChild(A.el(doc, 'li', '', t)); } });
  };
  A.renderConversation = function (doc, root, list) {
    A.clear(root);
    (list || []).slice().reverse().forEach(function (e) {
      var box = A.el(doc, 'div', 'qa');
      box.appendChild(A.el(doc, 'div', 'q', e.q));
      var a = e.state === 'answered' ? e.a : e.state === 'pending' ? 'Waiting for the answer…' : (e.message || 'No answer.');
      box.appendChild(A.el(doc, 'div', 'a', a));
      root.appendChild(box);
    });
  };
  A.renderSuggestions = function (doc, root, list, onPick) {
    A.clear(root);
    (list || []).forEach(function (s) {
      var b = A.el(doc, 'button', '', s.label);
      b.setAttribute('type', 'button');
      b.addEventListener('click', function () { onPick(s.id); });
      root.appendChild(b);
    });
  };
  A.statusLines = function (st) {
    var t = (st.status && st.status.text) || {};
    return [t.online, t.licensed, t.provider, t.learning, st.pin && st.pin.message];
  };
  return A;
})();
if (typeof module !== 'undefined') { module.exports = AIC; }
</script>
<script>
(function () {
  'use strict';
  var $ = function (id) { return document.getElementById(id); };
  var Q = AIC.parseQuery(location.search);
  var K = Q.k || '';
  var S = '';
  var last = null;
  var timer = null;
  var pin = '';
  var padFor = null;
  var touchedAt = 0;

  function show(id, on) { $(id).classList.toggle('hidden', !on); }
  function notice(text) { $('notice').textContent = text || ''; show('notice', !!text); }
  function url(path) { return path + '?k=' + encodeURIComponent(K) + '&s=' + encodeURIComponent(S); }
  function call(path, body, keepalive) {
    return fetch(url(path), {
      method: 'POST', cache: 'no-store', keepalive: !!keepalive,
      headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(body || {})
    }).then(function (r) { return r.json(); });
  }
  function offLan() {
    notice('Available on the home network only. Open this screen from a touch screen or a phone on the home Wi-Fi.');
  }
  function openSession() {
    return fetch('/session?k=' + encodeURIComponent(K), { method: 'POST', cache: 'no-store', body: '{}' })
      .then(function (r) { return r.json(); })
      .then(function (j) { if (!j.ok) { throw new Error('session'); } S = j.s; });
  }
  function schedule(ms) { clearTimeout(timer); timer = setTimeout(poll, ms); }
  function poll() {
    fetch(url('/state'), { cache: 'no-store' }).then(function (r) {
      if (r.status === 401) { return openSession().then(poll); }
      return r.json().then(function (st) { render(st); schedule(AIC.pollDelay(st)); });
    }).catch(function () { offLan(); schedule(15000); });
  }
  function act(path, body) {
    call(path, body).then(function (j) {
      if (j && j.ok === false && j.message) { notice(j.message); }
      poll();
    }).catch(offLan);
  }

  function render(st) {
    last = st;
    if (!st || !st.ok) { return; }
    AIC.renderLines(document, $('status'), AIC.statusLines(st));
    var chat = st.chat || {};
    $('chatMsg').textContent = chat.message || '';
    show('chatLocked', chat.available && chat.locked);
    show('chatOpen', chat.available && !chat.locked);
    if (chat.available && !chat.locked) {
      $('lockIn').textContent = AIC.leftText(chat.locks_in);
      AIC.renderConversation(document, $('conversation'), chat.conversation);
      AIC.renderSuggestions(document, $('suggestions'), chat.suggestions, function (id) { act('/ask', { suggestion_id: id }); });
    } else {
      AIC.clear($('conversation'));
      AIC.clear($('suggestions'));
      $('question').value = '';
    }
    var ap = st.approvals || {};
    $('apprCount').textContent = ap.text || '';
    $('apprMsg').textContent = ap.message || '';
    var rv = st.review;
    show('item', !!rv);
    show('review', !!ap.can_review && !rv);
    if (rv) {
      $('itemTitle').textContent = rv.loading ? 'Loading…' : (rv.title || '');
      $('itemDesc').textContent = rv.description || '';
      $('itemRisk').textContent = AIC.riskText(rv.risk);
      $('itemLeft').textContent = rv.loading ? '' : ('Decide within ' + rv.grant_left + ' s');
      $('approve').disabled = !!rv.loading;
      $('decline').disabled = !!rv.loading;
    }
    if (st.notice) { notice(st.notice); }
    var p = st.prompt;
    if (p && !p.waiting && p.challenge_id && AIC.validVerifyUrl(p.verify_url, location.hostname)) {
      if (padFor !== p.challenge_id) { openPad(p); }
    } else if (!p && padFor) {
      closePad();
    }
  }

  // ── the PIN pad: the PIN goes to PIN Lock's verify_url and nowhere else ──
  function drawDots() { $('padDots').textContent = AIC.dots(pin); }
  function openPad(p) {
    padFor = p.challenge_id;
    pin = '';
    drawDots();
    $('padTitle').textContent = p['for'] === 'chat' ? 'Owner PIN to open the chat' : 'Owner PIN to review one item';
    show('pad', true);
    $('padGo').focus();
  }
  function closePad() { pin = ''; padFor = null; drawDots(); show('pad', false); }
  function submitPin() {
    var p = last && last.prompt;
    if (!p || p.challenge_id !== padFor || !AIC.validVerifyUrl(p.verify_url, location.hostname) || !pin) { return; }
    var body = AIC.verifyBody(p.challenge_id, pin);
    var cid = p.challenge_id;
    pin = '';
    closePad();
    fetch(p.verify_url, { method: 'POST', cache: 'no-store', credentials: 'omit', headers: { 'Content-Type': 'text/plain' }, body: body })
      .then(function (r) { return r.json(); })
      .then(function (j) { if (j && j.locked) { notice(AIC.lockText(j.retry_in)); } })
      .catch(function () { notice('This screen could not reach PIN Lock. Use the SmartBuildOS portal.'); })
      .then(function () { act('/pin/done', { challenge_id: cid }); });
    body = null;
  }
  ['1', '2', '3', '4', '5', '6', '7', '8', '9', '', '0', '⌫'].forEach(function (k) {
    var b = AIC.el(document, 'button', '', k);
    b.setAttribute('type', 'button');
    if (!k) { b.disabled = true; b.setAttribute('aria-hidden', 'true'); }
    if (k === '⌫') { b.setAttribute('aria-label', 'Delete'); }
    b.addEventListener('click', function () { pin = k === '⌫' ? AIC.padBack(pin) : AIC.padAdd(pin, k); drawDots(); });
    $('keys').appendChild(b);
  });
  document.addEventListener('keydown', function (e) {
    if (!padFor) { return; }
    if (/^[0-9]$/.test(e.key)) { pin = AIC.padAdd(pin, e.key); drawDots(); e.preventDefault(); }
    else if (e.key === 'Backspace') { pin = AIC.padBack(pin); drawDots(); e.preventDefault(); }
    else if (e.key === 'Enter') { submitPin(); e.preventDefault(); }
    else if (e.key === 'Escape') { closePad(); act('/pin/cancel'); }
  });
  $('padGo').addEventListener('click', submitPin);
  $('padCancel').addEventListener('click', function () { closePad(); act('/pin/cancel'); });

  // ── actions ──
  $('unlock').addEventListener('click', function () { act('/chat/unlock'); });
  $('lock').addEventListener('click', function () { act('/chat/lock'); });
  $('ask').addEventListener('click', function () {
    var q = $('question').value;
    $('question').value = '';
    act('/ask', { question: q });
  });
  $('question').addEventListener('keydown', function (e) { if (e.key === 'Enter') { $('ask').click(); } });
  $('explain').addEventListener('click', function () { act('/ask', { explain: true }); });
  $('review').addEventListener('click', function () { act('/approvals/next'); });
  $('approve').addEventListener('click', function () { act('/approvals/decide', { decision: 'approve' }); });
  $('decline').addEventListener('click', function () { act('/approvals/decide', { decision: 'decline' }); });
  $('closeItem').addEventListener('click', function () { act('/approvals/close'); });
  ['pointerdown', 'keydown'].forEach(function (ev) {
    document.addEventListener(ev, function () {
      var now = Date.now();
      if (last && last.chat && !last.chat.locked && now - touchedAt > 30000) {
        touchedAt = now;
        call('/chat/touch').catch(function () {});
      }
    }, true);
  });
  document.addEventListener('visibilitychange', function () {
    if (document.hidden) { closePad(); if (S) { call('/chat/lock').catch(function () {}); } }
    else if (S) { poll(); }
  });
  window.addEventListener('pagehide', function () { if (S) { call('/session/close', {}, true).catch(function () {}); } });

  if (!K || location.protocol !== 'http:') { offLan(); return; }
  openSession().then(poll).catch(offLan);
})();
</script>
